const potRows=()=>Object.entries(potBal()).map(([k,v])=>({k,o:v.o,s:v.s,r:v.o-v.s})).filter(x=>x.o>0&&(S.unit==="all"||x.k===(S.unit==="all"?"":S.unit)));
function potSetor(){try{negAny();const u=$("#ps-u").value,d=$("#ps-d").value,k=db.cash_accounts.find(c=>c._id===$("#ps-k").value),raw=pn($("#ps-a").value||""),n=($("#ps-n").value||"").trim(),b=potBal()[u]||{o:0,s:0},r=b.o-b.s;
 if(!(u in potBal())||r<=0)throw fe("ps-u","Tidak ada potongan gaji yang perlu disetor untuk unit ini");
 if(!/^\d+(\.\d+)?$/.test(raw)||+raw<=0)throw fe("ps-a","Jumlah harus lebih dari 0");if(+raw>r)throw fe("ps-a","Jumlah melebihi saldo potongan (Rp "+fm(r)+")");
 if(!d)throw fe("ps-d","Tanggal setor wajib diisi");if(!k)throw fe("ps-k","Pilih kas/bank");if(!n)throw fe("ps-n","Tujuan setoran wajib diisi (mis. BPJS, koperasi, pajak)");
 post({type:REM_T,date:d,unit:u,desc:"Setor potongan gaji · "+n,lines:[{acc:"ACC2200",d:+raw},{acc:k.account_id,c:+raw}]});
 audit("remit","payroll","*",unitName(u)+" · "+n+" · Rp "+fm(+raw));save();okM();S.msg="Setoran potongan gaji Rp "+fm(+raw)+" dicatat"}catch(e){mErr(e);return}render()}
function batalSetorPot(id){try{const t=db.transactions.find(x=>x._id===id);if(!t||t.type!==REM_T||t.status!=="posted")throw Error("Setoran tidak ditemukan");rev(id);audit("void","payroll",id,t.description+" (setoran potongan)");save();S.msg="Setoran potongan dibatalkan dengan jurnal pembalik"}catch(e){S.msg="⚠ "+e.message}render()}
